insert into public.fact_estimate (metric_code, reference_year, source_id, universe, geo_level, geo_code, segment_json, segment_key, estimate, unit, standard_error, ci_low, ci_high, confidence_level, cv, precision_flag, observed_or_modeled, method_id, version, source_page, source_url, note) values
('denue_courier_establishments',2026,(select id from public.source_document where source_code='denue_api'),'Establecimientos del DENUE','municipality','01001','{}'::jsonb,'',84,'establecimientos',null,null,null,null,null,'high','observed',(select id from public.dim_method where method_code='official_published_aggregate'),'2026-10-19',null,'https://www.inegi.org.mx/servicios/api_denue.html','Sector SCIAN 492 (Mensajería y paquetería). Conteo del método Cuantificar del DENUE, estrato 0, en la cabecera de cada entidad y en las 16 alcaldías de la Ciudad de México. No es un censo de establecimientos que venden por internet. La densidad divide ese conteo entre la población adulta municipal publicada por la CNBV en marzo de 2026 (columna Población adulta, hoja BD Infraestructura Mun) y lo expresa por 10 mil adultos. Numerador y denominador son registros de fechas distintas; no es una tasa muestral y no trae intervalo.'),
